Voici un exemple de code en C# qui illustre l'utilisation de l'interface `IDisposable` et de la directive `using` pour gérer correctement les ressources non managées :

```csharp
using System;

// Classe qui implémente IDisposable pour gérer une ressource non managée
public class ResourceHolder : IDisposable
{
    private bool _disposed = false;
    private System.IO.StreamWriter _fileStream;

    public ResourceHolder(string filePath)
    {
        _fileStream = new System.IO.StreamWriter(filePath);
        Console.WriteLine("Ressource allouée");
    }

    public void WriteToFile(string message)
    {
        if (_disposed)
            throw new ObjectDisposedException("ResourceHolder");

        _fileStream.WriteLine(message);
        Console.WriteLine("Écriture dans le fichier");
    }

    // Implémentation de IDisposable
    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposed)
        {
            if (disposing)
            {
                // Libération des ressources managées
                if (_fileStream != null)
                {
                    _fileStream.Close();
                    _fileStream.Dispose();
                    _fileStream = null;
                }
            }

            // Libération des ressources non managées
            Console.WriteLine("Ressource libérée");

            _disposed = true;
        }
    }

    // Destructeur (finalizer)
    ~ResourceHolder()
    {
        Dispose(false);
    }
}

class Program
{
    static void Main()
    {
        // Utilisation de la directive using pour garantir la libération des ressources
        using (ResourceHolder resource = new ResourceHolder("test.txt"))
        {
            resource.WriteToFile("Bonjour, monde!");
        } // La méthode Dispose() est automatiquement appelée ici

        Console.WriteLine("Fin du programme");
    }
}
```

Explications :
1. La classe `ResourceHolder` implémente `IDisposable` pour gérer une ressource non managée (un `StreamWriter` dans ce cas).
2. La méthode `Dispose()` est utilisée pour libérer explicitement les ressources.
3. La directive `using` garantit que la méthode `Dispose()` est appelée automatiquement lorsque le bloc est quitté, même en cas d'exception.
4. Le destructeur (finalizer) est une sauvegarde au cas où l'objet ne serait pas correctement disposé.

Ce pattern est particulièrement utile pour gérer des ressources comme des fichiers, des connexions réseau, des handles de fenêtres, etc.
